<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\{Audit,Auth,Csrf,Database,Flash,Http,View};final class AdminController{public function users():void{Auth::requirePermission('users.manage');$pdo=Database::pdo();$users=$pdo->query('SELECT u.id,u.email,u.name,u.phone,u.account_status,u.active,u.is_demo,r.code role_code,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.deleted_at IS NULL ORDER BY FIELD(u.account_status,\'PENDING_ASSIGNMENT\',\'ACTIVE\',\'SUSPENDED\',\'INACTIVE\'),u.name')->fetchAll();$roles=$pdo->query('SELECT id,code,name FROM roles ORDER BY sort_order')->fetchAll();$regions=$pdo->query('SELECT id,name FROM regions WHERE active=1 ORDER BY name')->fetchAll();$parks=$pdo->query('SELECT id,name,region_id FROM parks WHERE active=1 ORDER BY name')->fetchAll();$areas=$pdo->query('SELECT id,name FROM areas WHERE active=1 ORDER BY name')->fetchAll();$positions=$pdo->query('SELECT id,name FROM positions WHERE active=1 ORDER BY name')->fetchAll();View::render('admin/users',compact('users','roles','regions','parks','areas','positions')+['flash'=>Flash::pull()]);}public function assign():void{Auth::requirePermission('users.manage');Csrf::verify($_POST['_csrf']??null);$pdo=Database::pdo();$uid=(int)($_POST['user_id']??0);$rid=(int)($_POST['role_id']??0);$type=in_array($_POST['assignment_type']??'', ['PARK','CORPORATE','OTHER'],true)?$_POST['assignment_type']:'OTHER';$region=(int)($_POST['region_id']??0)?:null;$park=(int)($_POST['park_id']??0)?:null;$area=(int)($_POST['area_id']??0)?:null;$pos=(int)($_POST['position_id']??0)?:null;$old=$pdo->prepare('SELECT role_id,account_status FROM users WHERE id=?');$old->execute([$uid]);$before=$old->fetch();if(!$before)throw new \RuntimeException('Usuario no encontrado.');Database::transaction(function($pdo)use($uid,$rid,$type,$region,$park,$area,$pos,$before){$pdo->prepare('UPDATE user_assignments SET ended_at=NOW() WHERE user_id=? AND ended_at IS NULL')->execute([$uid]);$pdo->prepare('INSERT INTO user_assignments(user_id,region_id,park_id,area_id,position_id,assignment_type,started_at,created_by) VALUES(?,?,?,?,?,?,NOW(),?)')->execute([$uid,$region,$park,$area,$pos,$type,Auth::id()]);if((int)$before['role_id']!==$rid){$pdo->prepare('UPDATE user_role_history SET ended_at=NOW() WHERE user_id=? AND ended_at IS NULL')->execute([$uid]);$pdo->prepare('INSERT INTO user_role_history(user_id,role_id,started_at,reason,changed_by) VALUES(?,?,NOW(),?,?)')->execute([$uid,$rid,'Asignación administrativa Helpdesk',Auth::id()]);}$pdo->prepare("UPDATE users SET role_id=?,account_status='ACTIVE',updated_at=NOW() WHERE id=?")->execute([$rid,$uid]);});Audit::log('USER_ASSIGNMENT_UPDATED','user',$uid,$before,['role_id'=>$rid,'assignment_type'=>$type,'region_id'=>$region,'park_id'=>$park,'area_id'=>$area,'position_id'=>$pos]);Flash::set('Usuario asignado y activado.','success');header('Location: '.APP_BASE_URL.'/admin/users');exit;}}
